<template>
  <div class="reply-list" >
    <div class="mescroll" ref="pageMScroll">
      <div>
        <div class="title">
          <div>商品评价({{count}})</div>
          <div>
            <span>好评度</span>
            <span class="red">{{satisfaction}}%</span>
          </div>
        </div>
        <div class="list">
          <div class="item" v-for="(item, index) in list" :key="index">
            <div class="name-box">
              <div>
                <img class="avatar" :src="item.avatar" alt="">
                <span>{{item.nickname}}</span>
              </div>
              <div class="star-box">
                <i class="icon iconfont full" v-for="goodNum in item.level*1">&#xe697;</i>
                <i class="icon iconfont empty"  v-for="badNum in (3 - item.level*1)">&#xe625;</i>
              </div>
            </div>
            <div class="desc-box">
              <div>
                <span v-if="item.level == 3">非常满意</span>
                <span v-if="item.level == 2">满意</span>
                <span v-if="item.level == 1">一般</span>
              </div>
              <div class="time">{{item.add_time}}</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import MeScroll from 'mescroll.js'
export default {
  name: 'Reply',
  data () {
    return {
      list: [],
      page: 1,
      isComplete: false,
      pageScroll: '',
      count: 0,
      satisfaction: 100
    }
  },
  created () {
    console.log('33333333', this.$route.query)
    this.count = this.$route.query.count
    this.satisfaction = this.$route.query.satisfaction
    this.goods_id = this.$route.query.goodsId
    this.leader_id = this.$route.query.leaderId
    this.getReplyList()
  },
  methods: {
    async getReplyList () {
      let param = {
        leader_id: this.leader_id,
        goods_id: this.goods_id,
        page: this.page
      }
      let res = await this.$api.getReply(param)
      if (!res) return
      if (this.page == 1) {
        this.list = []
      }
      this.list = this.list.concat(res)
      if (res.length < 20) {
        this.isComplete = true
      } else {
        this.page++
      }
      if (!this.pageScroll) {
        this.initialScroll()
      } else {
        this.pageScroll.endSuccess(res.length, !this.isComplete)
      }
    },
    // 初始化滚动插件
    initialScroll () {
      let _this = this
      this.$nextTick(function () {
        this.pageScroll = new MeScroll(this.$refs.pageMScroll, {
          down: {
            isLock: true
          },
          up: {
            auto: false,
            callback: _this.getReplyList,
            lazyLoad: {
              use: true
            },
            htmlNodata: '<p class="upwarp-nodata">已经到底了...</p>',
            noMoreSize: 2
          }
        })
      })
    }
  }
}
</script>

<style lang="stylus" scoped>
.reply-list
  background #fff
  color #333
  .title
    flexbox()
    justify-content space-between
    margin 0 15px
    padding 15px 0
    border-bottom 1PX solid #efefef
    font-size 14px
    .red
      color red
      padding-left 5px
  .list
    .item
      margin 0 15px
      padding 15px 0
      border-bottom 1PX solid #efefef
      .name-box
        flexbox()
        justify-content space-between
        padding-bottom 15px
        .avatar
          display inline-block
          width 30px
          height 30px
          border-radius 50%
          background #efefef
          vertical-align middle
          margin-right 5px
        .star-box
          color #ffc915
          padding-top 5px
          .icon
            padding-left 5px
      .desc-box
        flexbox()
        justify-content space-between
        .time
          color #999
</style>
